var DATE_TIME_REGEX = /^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[1-2][0-9]|3[0-1])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](\.[0-9]+)?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])$/;
var RECURRING_SERIES_ID_REGEX = /^RI-[A-Z0-9]{17}$/;
var COUNTRY_CODE_REGEX = /^([A-Z]{2}|C2)$/;
